import * as THREE from 'three/webgpu';
import { MeshPhysicalNodeMaterial, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-journal-badge';
  group.position.set(2.5, -0.19999999999999996, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  let mesh = null;
  const capsule = new THREE.Group();
  group.add(capsule);

  const meshUrl = '/prism-mock/orrery/meshes/gear-a.glb';
  const gltf = ctx.glbLoader(meshUrl);
  if (gltf && gltf.scene) {
    mesh = gltf.scene.clone(true);
    mesh.traverse((child) => {
      if (child.isMesh) {
        child.castShadow = true;
        child.receiveShadow = true;
      }
    });
    capsule.add(mesh);
  }

  // Accent rim light on the edge of the capsule badge
  const rimLight = new THREE.PointLight(0xff2a38, 1.2, 2.5, 2.0);
  rimLight.position.set(0.3, 0.1, 0.4);
  capsule.add(rimLight);

  const rimLight2 = new THREE.PointLight(0xff2a38, 0.5, 1.5, 2.0);
  rimLight2.position.set(-0.3, -0.1, -0.2);
  capsule.add(rimLight2);

  // Apply cinematic primitives via ctx.primitives
  const primitiveHandles = [];
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((primitive) => {
      if (ctx.primitives && ctx.primitives[primitive.name]) {
        const handle = ctx.primitives[primitive.name](group, primitive.params);
        primitiveHandles.push(handle);
      }
    });
  }

  const timelines = [];
  const basePosY = group.position.y;

  // weighted-settle entrance
  gsap.set(group.scale, { x: 1.04, y: 1.04, z: 1.04 });
  gsap.set(group.position, { y: basePosY - 0.1 });
  const settleTl = gsap.timeline();
  settleTl.to(group.scale, {
    x: 1, y: 1, z: 1,
    duration: 0.9,
    ease: 'power4.out',
  }, 0);
  settleTl.to(group.position, {
    y: basePosY,
    duration: 0.9,
    ease: 'power4.out',
  }, 0);
  timelines.push(settleTl);

  // hover: rise-in subtle
  let hoverTl = null;
  const onHoverIn = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, {
      y: basePosY + 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    timelines.push(hoverTl);
  };
  const onHoverOut = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(group.position, {
      y: basePosY,
      duration: 0.7,
      ease: 'power3.out',
    });
    timelines.push(hoverTl);
  };

  // click: emit navigation event
  const onClick = () => {
    const pressTl = gsap.timeline();
    pressTl.to(group.scale, {
      x: 0.97, y: 0.97, z: 0.97,
      duration: 0.12,
      ease: 'back.out',
      yoyo: true,
      repeat: 1,
    });
    timelines.push(pressTl);

    if (group.userData.emit) {
      group.userData.emit('hub-journal.select', { source: 'hub-journal-badge' });
    }
  };

  group.userData.handlers = {
    hover: onHoverIn,
    hoverIn: onHoverIn,
    hoverOut: onHoverOut,
    click: onClick,
  };

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    if (settleTl) settleTl.kill();
    if (hoverTl) hoverTl.kill();

    rimLight.dispose && rimLight.dispose();
    rimLight2.dispose && rimLight2.dispose();

    if (mesh) {
      mesh.traverse((child) => {
        if (child.isMesh) {
          if (child.geometry) child.geometry.dispose();
          if (child.material) {
            if (Array.isArray(child.material)) {
              child.material.forEach((m) => m.dispose());
            } else {
              child.material.dispose();
            }
          }
        }
      });
    }

    primitiveHandles.forEach((handle) => {
      if (handle && typeof handle.dispose === 'function') {
        handle.dispose();
      }
    });
  };

  return group;
}
